// 1) Une interface SCELLEE : elle fixe la liste fermee de ses sous types.
sealed interface Forme permits Cercle, Rectangle { }

// 2) Des RECORDS pour les sous types : donnees immuables, courtes a ecrire.
record Cercle(double rayon) implements Forme { }
record Rectangle(double largeur, double hauteur) implements Forme { }

// 3) Un SWITCH avec pattern matching : un cas par sous type, et rien d'autre.
static double aire(Forme f) {
    return switch (f) {
        case Cercle c -> Math.PI * c.rayon() * c.rayon();
        case Rectangle r -> r.largeur() * r.hauteur();
        // Pas de default : les deux seuls cas possibles sont couverts.
    };
}

