// L'interface scellee : la liste fermee des formes possibles.
sealed interface Forme permits Cercle, Rectangle, Triangle { }

// Chaque variante est un record : donnees immuables, une ligne chacune.
record Cercle(double rayon) implements Forme { }
record Rectangle(double largeur, double hauteur) implements Forme { }
record Triangle(double base, double hauteur) implements Forme { }

public class Demo {
    public static void main(String[] args) {
        Forme f = new Cercle(2.0);
        System.out.println(f); // Cercle[rayon=2.0]  (toString gratuit du record)
    }
}

