sealed interface Forme permits Cercle, Rectangle, Triangle { }
record Cercle(double rayon) implements Forme { }
record Rectangle(double largeur, double hauteur) implements Forme { }
record Triangle(double base, double hauteur) implements Forme { }

static double aire(Forme f) {
    // Un case par sous type permis. Pas de default : c'est volontaire.
    return switch (f) {
        case Cercle c -> Math.PI * c.rayon() * c.rayon();
        case Rectangle r -> r.largeur() * r.hauteur();
        case Triangle t -> (t.base() * t.hauteur()) / 2;
    };
    // Le compilateur accepte : les trois seuls cas possibles sont couverts.
}

static double aire(Forme f) {
    return switch (f) {
        // On extrait directement les composants : plus de c.rayon().
        case Cercle(double r) -> Math.PI * r * r;
        case Rectangle(double larg, double haut) -> larg * haut;
        case Triangle(double base, double haut) -> (base * haut) / 2;
    };
}
// Toujours exhaustif, toujours sans default, et plus direct a lire.

