// On etend la liste fermee avec une nouvelle variante.
sealed interface Forme permits Cercle, Rectangle, Triangle, Losange { }
record Cercle(double rayon) implements Forme { }
record Rectangle(double largeur, double hauteur) implements Forme { }
record Triangle(double base, double hauteur) implements Forme { }
record Losange(double diagonale1, double diagonale2) implements Forme { }

static double aire(Forme f) {
    return switch (f) {           // ERREUR DE COMPILATION ici.
        case Cercle c -> Math.PI * c.rayon() * c.rayon();
        case Rectangle r -> r.largeur() * r.hauteur();
        case Triangle t -> (t.base() * t.hauteur()) / 2;
        // Il manque le cas Losange -> le switch n'est plus exhaustif.
    };
}

static double aire(Forme f) {
    return switch (f) {
        case Cercle c -> Math.PI * c.rayon() * c.rayon();
        case Rectangle r -> r.largeur() * r.hauteur();
        case Triangle t -> (t.base() * t.hauteur()) / 2;
        // Cas ajoute : le compilateur nous avait pointe exactement ici.
        case Losange l -> (l.diagonale1() * l.diagonale2()) / 2;
    };
    // De nouveau exhaustif -> compile a nouveau. Aucun oubli possible.
}

// Liste fermee des formes d'expression possibles.
sealed interface Expr permits Nombre, Addition, Multiplication { }

// Une feuille : juste une valeur.
record Nombre(double valeur) implements Expr { }

// Deux noeuds : chacun porte deux sous expressions (type recursif).
record Addition(Expr gauche, Expr droite) implements Expr { }
record Multiplication(Expr gauche, Expr droite) implements Expr { }

// Exemple : (2 + 3) * 4
// new Multiplication(new Addition(new Nombre(2), new Nombre(3)), new Nombre(4))

classDiagram
    class Expr {
        <<sealed interface>>
    }
    class Nombre {
        <<record>>
        +double valeur
    }
    class Addition {
        <<record>>
        +Expr gauche
        +Expr droite
    }
    class Multiplication {
        <<record>>
        +Expr gauche
        +Expr droite
    }
    Expr <|.. Nombre
    Expr <|.. Addition
    Expr <|.. Multiplication
    Addition o-- Expr
    Multiplication o-- Expr

static double evaluer(Expr e) {
    return switch (e) {
        // Deconstruction du record : on recupere directement les composants.
        case Nombre(double v) -> v;
        case Addition(Expr g, Expr d) -> evaluer(g) + evaluer(d);
        case Multiplication(Expr g, Expr d) -> evaluer(g) * evaluer(d);
        // Exhaustif, sans default : les trois variantes d'Expr sont couvertes.
    };
}

public class Demo {
    public static void main(String[] args) {
        // (2 + 3) * 4
        Expr e = new Multiplication(
            new Addition(new Nombre(2), new Nombre(3)),
            new Nombre(4));
        System.out.println(evaluer(e)); // 20.0
    }
}
